-- 매핑된 클래스의 폴백 영양값을 정본으로 동기화한다.
-- 앱 미리보기(catalog)와 서버 계산값의 차이를 줄이는 목적이다.
UPDATE public.cm_food_class c
   SET fb_kcal      = n.kcal,
       fb_carb_g    = n.carb_g,
       fb_protein_g = n.protein_g,
       fb_fat_g     = n.fat_g,
       updated_at   = now()
  FROM public.cm_food_nutrition n
 WHERE n.food_code = c.food_code
   AND n.nutrition_version = 'MFDS-2025.12'
   AND n.is_enabled = true;

SELECT count(*) AS loaded FROM public.cm_food_nutrition WHERE nutrition_version = 'MFDS-2025.12';
